WITH recent_products AS (SELECT * FROM products WHERE stock_qty = 283 AND cost >= 190 AND cost IS NOT NULL), products_stats AS (SELECT CASE WHEN stock_qty >= 324 THEN 'high' WHEN stock_qty >= 64 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, SUM(CASE WHEN category = 'Fashion' THEN 1 ELSE 0 END) AS fashion_count FROM recent_products GROUP BY CASE WHEN stock_qty >= 324 THEN 'high' WHEN stock_qty >= 64 THEN 'mid' ELSE 'low' END) SELECT * FROM products_stats WHERE fashion_count >= 67 ORDER BY fashion_count DESC, stock_qty_bucket LIMIT 10;
